/// Read `w` bits of a GameCube big-endian bitfield byte run, `shift` bits up from its LSB.
#[inline]
fn melee_core_bits_get(b: &[u8], shift: u32, w: u32) -> u64 {
    let mut v: u128 = 0;
    for &x in b { v = (v << 8) | x as u128; }
    ((v >> shift) as u64) & (((1u128 << w) - 1) as u64)
}
#[inline]
fn melee_core_bits_set(b: &mut [u8], shift: u32, w: u32, val: u64) {
    let mut v: u128 = 0;
    for &x in b.iter() { v = (v << 8) | x as u128; }
    let m = ((1u128 << w) - 1) << shift;
    v = (v & !m) | (((val as u128) << shift) & m);
    for x in b.iter_mut().rev() { *x = v as u8; v >>= 8; }
}
